#{code}
AND MATERIAL_CODE IN
#{code}
AND (IS_DELETE = 0 OR IS_DELETE IS NULL) GROUP BY FACTORY_CODE, MATERIAL_CODE, LH_TYPE

SELECT FACTORY_CODE, MATERIAL_CODE, CLASS1_LH_TYPE, SUM(CLASS1_FINISH_QTY) AS TOTAL_FINISH_QTY FROM T_LH_SCHE_FINISH_QTY WHERE SCHEDULE_DATE >= #{scheduleDate} AND SCHEDULE_DATE < #{nextDayStart} AND FACTORY_CODE IN
#{code}
